#!/usr/bin/env node
// NASO Refresh — bring an already-set-up repository up to the current tool.
//
// Three things, and deliberately not a fourth:
//
//   1. Re-copy the toolset into `<repo>/.naso/tooling/`, with this version's VERSION.
//   2. Move the AGENTS.md version stamp forward, and say the refresh on the "Generated by"
//      line. No other word of the block changes.
//   3. Reinstall the pre-commit hook, so it points at the freshly copied scripts.
//
// What it will not do, and the reason is the whole design of this command:
//
//   It never rewrites AGENTS.md content. A briefing somebody spent twenty minutes on, or
//   an agent added a section to, is theirs; a version bump is not a licence to throw that
//   away. If the content needs regenerating, that is `briefing create --force`.
//
//   It never rewrites the settings in `.naso/config.json`. That file records decisions a
//   human made about this repository — which areas stay out of the briefing, local or
//   tracked mode. An upgrade is not a reason to re-ask those questions. The one key it
//   removes is `generatedBy`, the user and machine name versions before 1.1.1 recorded.
//
// The stamp only ever moves forward. A briefing written by a newer NASO than the tool
// running the refresh is reported and left alone: downgrading the stamp would destroy the
// only record that the tool, not the briefing, is out of date.
//
// Usage:
//   npx naso-dev refresh [target-dir]
//
// Zero external dependencies — Node.js core modules only.

import path from 'node:path';
import {
  parseArgs,
  pathExists,
  toolVersion,
  compareVersions,
  isMainModule,
  SUPPORT_EMAIL,
  nasoCommand,
  nasoUpgradeCommand,
  exactDevInstallText,
  detectPackageManager,
  readJSONFile,
  recordedNasoVersion,
} from './lib.mjs';
import { refreshBriefingStamp, AGENTS_FILE } from './briefing.mjs';
import { installPreCommitHook, readHook, isNasoHook } from './install.mjs';
import { NASO_DIR, isVendored, vendorTooling, vendoredVersion, readConfig, dropLegacyIdentity } from './vendor.mjs';

export async function main(argv = process.argv.slice(2)) {
  const { flags, positional } = parseArgs(argv);

  if (flags.has('help') || flags.has('h')) {
    console.log(`NASO refresh

Usage:
  ${nasoCommand()} refresh [target-dir]

  Re-copies the toolset into ${NASO_DIR}/tooling/, moves the AGENTS.md version stamp
  forward, and reinstalls the pre-commit hook. Refuses to move a newer toolset back
  unless --force is passed.

  Changes no other AGENTS.md prose than the refresh note on its "Generated by" line, and
  never rewrites ${NASO_DIR}/config.json, which records the version setup ran with.
  To regenerate the briefing itself: ${nasoCommand()} briefing <dir> create --force

Support: ${SUPPORT_EMAIL}`);
    return;
  }

  const cwd = path.resolve(positional[0] ?? process.cwd());

  if (!(await pathExists(cwd))) {
    console.error(`naso-dev refresh: target directory does not exist: ${cwd}`);
    process.exitCode = 1;
    return;
  }

  const version = await toolVersion();
  console.log(`# NASO Refresh ${version} — ${cwd}`);
  console.log('');

  const hadTooling = await isVendored(cwd);
  const hadBriefing = await pathExists(path.join(cwd, AGENTS_FILE));

  if (!hadTooling && !hadBriefing) {
    console.log('This repository is not set up yet. Nothing to refresh.');
    console.log('');
    console.log(`  ${nasoCommand()} setup ${cwd}`);
    console.log('');
    process.exitCode = 1;
    return;
  }

  let problems = 0;

  // A teammate refreshed with a newer NASO, and this run comes from an older install
  // (node_modules still on the version package.json records). Re-copying would quietly
  // undo their upgrade and every fix in it, so it is refused unless asked for by name.
  const current = await vendoredVersion(cwd);
  if (current && compareVersions(current, version) > 0 && !flags.has('force')) {
    console.log(`--  ${NASO_DIR}/tooling/ is ${current}, newer than this tool (${version}). Nothing was changed.`);
    console.log(`    Bring the package up to the toolset: ${exactDevInstallText((await detectPackageManager(cwd, await readJSONFile(path.join(cwd, 'package.json')))).name, current)}`);
    console.log(`    Or move the toolset back to ${version} on purpose: ${nasoCommand()} refresh --force`);
    process.exitCode = 1;
    return;
  }

  // 1. The toolset.
  const vendored = await vendorTooling(cwd, { version });
  console.log(`OK  Re-copied ${vendored.length} files into ${NASO_DIR}/tooling/.`);
  if (!hadTooling) {
    console.log('    It was not there before, so this run set the repository up as well.');
  }

  // 2. The stamp. Forward only.
  if (!hadBriefing) {
    console.log(`--  No ${AGENTS_FILE} here, so there is no stamp to move.`);
    console.log(`    The gate still works; run \`${nasoCommand()} setup ${cwd}\` for the briefing.`);
  } else {
    const stamped = await refreshBriefingStamp(cwd, { current: version });
    if (!stamped.ok) {
      if (stamped.reason === 'unstamped') {
        console.log(`--  ${AGENTS_FILE} has no version stamp, so nothing to move.`);
        console.log(`    \`${nasoCommand()} briefing ${cwd} create --force\` would write one.`);
      } else {
        console.log(`--  Could not read ${AGENTS_FILE}: ${stamped.reason}`);
        problems++;
      }
    } else if (compareVersions(stamped.previous, version) > 0) {
      // Checked before `changed`: a newer stamp is also unchanged, and reporting it as
      // "already stamped" hid the one case where the tool, not the briefing, is behind.
      console.log(`--  ${AGENTS_FILE} is stamped ${stamped.previous}, newer than this tool (${version}).`);
      console.log('    Left it alone: the tool is what needs updating here, not the briefing.');
      console.log(`    Run \`${nasoUpgradeCommand()}\`, or \`${nasoCommand({ version: 'latest' })} refresh\`, to catch up.`);
    } else if (!stamped.changed) {
      console.log(`--  ${AGENTS_FILE} is already stamped ${version}.`);
    } else {
      console.log(`OK  Moved the ${AGENTS_FILE} stamp ${stamped.previous} -> ${version}. No prose touched.`);
    }
  }

  // 3. The hook.
  const hook = await readHook(cwd);
  if (hook && !isNasoHook(hook)) {
    console.log(`--  ${hook.path} is a hook NASO did not write. Left it as it is.`);
  } else {
    // A NASO hook already living in a tracked core.hooksPath was put there by a person's
    // explicit choice at setup; rewriting our own file there is not a new decision.
    const installed = await installPreCommitHook(cwd, { report: () => {}, allowTracked: isNasoHook(hook) });
    if (installed.ok) {
      console.log(`OK  Reinstalled the pre-commit hook: ${installed.hookPath}`);
    } else {
      console.log(`--  Skipped the pre-commit hook: ${installed.reason}.`);
      console.log(`    To run the gate by hand: node ${NASO_DIR}/tooling/validate.mjs --staged`);
    }
  }

  // Reported, never rewritten — with one exception. Before 1.1.1 setup recorded the
  // user and machine name as `generatedBy`; that key is removed and nothing else moves.
  const droppedIdentity = await dropLegacyIdentity(cwd);
  const config = await readConfig(cwd);
  const excluded = Array.isArray(config.exclude) ? config.exclude : [];
  console.log('');
  console.log(
    droppedIdentity
      ? `   ${NASO_DIR}/config.json: removed the user and machine name older versions recorded; nothing else changed`
      : `   ${NASO_DIR}/config.json: left exactly as it was`,
  );
  console.log(
    excluded.length > 0
      ? `   ${excluded.length} area(s) excluded from the briefing: ${excluded.join(', ')}`
      : '   no areas excluded from the briefing',
  );

  console.log('');
  const toolset = (await vendoredVersion(cwd)) ?? version;
  console.log(`Toolset version in this repository: ${toolset}`);
  const recorded = await recordedNasoVersion(cwd);
  const recordedVersion = recorded ? (recorded.installed ?? recorded.spec.replace(/^[\^~=v]+/, '')) : null;
  if (recordedVersion && recordedVersion !== toolset) {
    console.log(`package.json records naso-dev ${recorded.spec}${recorded.installed ? ` (installed ${recorded.installed})` : ''}; teammates who install get that, not ${toolset}.`);
    console.log(`  To match: ${exactDevInstallText((await detectPackageManager(cwd, recorded.pkg)).name, toolset)}`);
  }
  console.log('');
  console.log('Next:');
  console.log(`  ${nasoCommand()} doctor ${cwd}       confirm the install end to end`);
  console.log(`  ${nasoCommand()} validate ${cwd}     run the full gate once, not just the staged one`);
  console.log('');

  if (problems > 0) process.exitCode = 1;
}

if (isMainModule(import.meta.url)) {
  main().catch((err) => {
    console.error(`naso-dev refresh: unexpected error — ${err?.stack ?? err}`);
    console.error(`Support: ${SUPPORT_EMAIL}`);
    process.exitCode = 1;
  });
}
